targets.expr:
topk(
    10,
    max(max_over_time(cardinality_churn_ratio{
            job="$job",
            group_by_keys=~"$group_by_keys",
            group_by_keys!="__global__",
            group_by_keys!="__group__",
            group_by_values=~"$group_by_values"
    }[15s])) by (job,group_by_values)
)

topk(
    10,
    max(
        cardinality_estimate{job="$job",interval=~"$interval",group_by_keys=~"$group_by_keys",group_by_keys!="__global__",group_by_keys!="__group__",group_by_values=~"$group_by_values"}
    ) by (job, group_by_values)
    *
    max (
        max_over_time(cardinality_churn_ratio{job="$job",interval=~"$interval",group_by_keys=~"$group_by_keys",group_by_keys!="__global__",group_by_keys!="__group__",group_by_values!~"by_.+",group_by_values=~"$group_by_values"}[5m])
    ) by (job, group_by_values)
)
